STYLE = ''':root{--bg:#0a0d12;--panel:#111722;--panel2:#161e2b;--line:#253043;--text:#edf2f7;--muted:#8e9bad;--green:#35d07f;--amber:#f5b942;--red:#f06d6d;--violet:#9580ff;--cyan:#63d5e8}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 12% 0,#18243b 0,transparent 35%),var(--bg);color:var(--text);font:14px/1.45 ui-sans-serif,system-ui,sans-serif}main{max-width:1500px;margin:auto;padding:28px}header{display:flex;justify-content:space-between;align-items:center}.eyebrow{color:var(--cyan);text-transform:uppercase;letter-spacing:.16em;font-size:11px;font-weight:700}h1{font-size:30px;margin:6px 0}.panel,.column,.card,.tile{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:16px}#login{max-width:440px;margin:60px auto}label{display:block;color:var(--muted);margin:14px 0}input{display:block;width:100%;margin-top:5px;padding:10px;background:var(--panel2);border:1px solid var(--line);border-radius:5px;color:var(--text)}button{background:var(--violet);border:0;border-radius:6px;color:#fff;padding:9px 12px;cursor:pointer}nav{display:flex;gap:8px;margin:22px 0;overflow:auto}nav button:not(.active){background:transparent;color:var(--muted);border:1px solid var(--line)}.board{display:grid;grid-template-columns:repeat(5,minmax(220px,1fr));gap:12px;overflow:auto}.column{min-height:240px}.card{margin:10px 0;background:var(--panel2);cursor:pointer}.meta,.empty{color:var(--muted)}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.tile strong{display:block;font-size:22px}.tile span{color:var(--muted)}table{width:100%;border-collapse:collapse}.table-wrap{overflow:auto}th,td{padding:8px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}th{color:var(--muted)}pre{white-space:pre-wrap;max-height:500px;overflow:auto;background:#07090d;padding:12px;border-radius:7px}.actions{margin-top:9px}dialog{width:min(900px,calc(100% - 24px));max-height:90vh;overflow:auto;background:var(--panel);color:var(--text);border:1px solid var(--line);border-radius:12px}#login-error,.error{color:var(--red)}a{color:var(--cyan)}@media(max-width:900px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}main{padding:18px 12px}}'''
